CREATE FUNCTION private.wave6_operation_tuple_before() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $function$
BEGIN
 -- Trusted existing postgres/service-role workflows remain untouched; no caller receives those roles here.
 IF current_user NOT IN ('authenticated','anon') THEN RETURN NEW; END IF;
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authenticated actor required' USING ERRCODE='42501'; END IF;
 IF TG_TABLE_NAME='client_checkins' THEN
  IF TG_OP='INSERT' AND NEW.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Check-in actor mismatch' USING ERRCODE='42501'; END IF;
  IF TG_OP='UPDATE' AND ROW(NEW.contact_id,NEW.membership_id,NEW.template_id,NEW.period_start,NEW.period_end,NEW.created_by,NEW.responses) IS DISTINCT FROM ROW(OLD.contact_id,OLD.membership_id,OLD.template_id,OLD.period_start,OLD.period_end,OLD.created_by,OLD.responses) THEN RAISE EXCEPTION 'Check-in source tuple is immutable' USING ERRCODE='42501'; END IF;
  IF NEW.reviewed_by IS NOT NULL AND (TG_OP='INSERT' OR NEW.reviewed_by IS DISTINCT FROM OLD.reviewed_by) AND NEW.reviewed_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Reviewer actor mismatch' USING ERRCODE='42501'; END IF;
 ELSIF TG_TABLE_NAME='client_assignments' THEN
  IF TG_OP='INSERT' AND NEW.assigned_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Assignment actor mismatch' USING ERRCODE='42501'; END IF;
  IF TG_OP='UPDATE' AND ROW(NEW.contact_id,NEW.membership_id,NEW.assigned_by) IS DISTINCT FROM ROW(OLD.contact_id,OLD.membership_id,OLD.assigned_by) THEN RAISE EXCEPTION 'Assignment source tuple is immutable' USING ERRCODE='42501'; END IF;
 ELSIF TG_TABLE_NAME='household_members' THEN
  IF TG_OP='UPDATE' AND ROW(NEW.household_id,NEW.contact_id,NEW.relationship_type,NEW.sex,NEW.is_primary,NEW.date_of_birth,NEW.guardian_contact_id) IS DISTINCT FROM ROW(OLD.household_id,OLD.contact_id,OLD.relationship_type,OLD.sex,OLD.is_primary,OLD.date_of_birth,OLD.guardian_contact_id) THEN RAISE EXCEPTION 'Household identity change requires separately reviewed workflow' USING ERRCODE='42501'; END IF;
  IF TG_OP='INSERT' AND NEW.guardian_contact_id IS NOT NULL THEN RAISE EXCEPTION 'New guardian binding requires separately reviewed workflow' USING ERRCODE='42501'; END IF;
 END IF;
 RETURN NEW;
END;
$function$;
ALTER FUNCTION private.wave6_operation_tuple_before() OWNER TO postgres;
REVOKE ALL ON FUNCTION private.wave6_operation_tuple_before() FROM PUBLIC,anon,authenticated,service_role;
CREATE POLICY wave6_client_checkins_scope_select ON public.client_checkins AS RESTRICTIVE FOR SELECT TO authenticated USING (((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'coaching.view',contact_id)) OR (contact_id IN (SELECT ca.contact_id FROM public.client_access ca WHERE ca.user_id=auth.uid() AND ca.status='active' AND NOT ca.needs_onboarding_claim))));
CREATE POLICY wave6_client_checkins_scope_insert ON public.client_checkins AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'coaching.manage',contact_id)) OR (contact_id IN (SELECT ca.contact_id FROM public.client_access ca WHERE ca.user_id=auth.uid() AND ca.status='active' AND NOT ca.needs_onboarding_claim))) AND (client_checkins.membership_id IS NULL OR EXISTS(SELECT FROM public.client_memberships cm WHERE cm.id=client_checkins.membership_id AND cm.status='active' AND (cm.primary_contact_id=client_checkins.contact_id OR EXISTS(SELECT FROM public.client_access ca WHERE ca.membership_id=cm.id AND ca.contact_id=client_checkins.contact_id AND ca.status IN('active','ready')))))));
CREATE POLICY wave6_client_checkins_scope_update ON public.client_checkins AS RESTRICTIVE FOR UPDATE TO authenticated USING (((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'coaching.manage',contact_id)) AND (client_checkins.membership_id IS NULL OR EXISTS(SELECT FROM public.client_memberships cm WHERE cm.id=client_checkins.membership_id AND cm.status='active' AND (cm.primary_contact_id=client_checkins.contact_id OR EXISTS(SELECT FROM public.client_access ca WHERE ca.membership_id=cm.id AND ca.contact_id=client_checkins.contact_id AND ca.status IN('active','ready'))))))) WITH CHECK (((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'coaching.manage',contact_id)) AND (client_checkins.membership_id IS NULL OR EXISTS(SELECT FROM public.client_memberships cm WHERE cm.id=client_checkins.membership_id AND cm.status='active' AND (cm.primary_contact_id=client_checkins.contact_id OR EXISTS(SELECT FROM public.client_access ca WHERE ca.membership_id=cm.id AND ca.contact_id=client_checkins.contact_id AND ca.status IN('active','ready')))))));
